previewCss:
.darma-loader-darma-b14-cocktail-shake { --accent: var(--loader-color, #e11d48); --accent-2: var(--loader-secondary-color, #94a3b8); width: var(--loader-size, 108px); height: var(--loader-size, 108px); display: grid; place-items: center; }
.darma-loader-darma-b14-cocktail-shake .darma-loader-darma-b14-cocktail-shake__shaker { position: relative; width: 40%; height: 70%; overflow: hidden; border-radius: 12% 12% 20% 20%; background: linear-gradient(100deg, color-mix(in srgb, #fff 38%, var(--accent-2)), var(--accent-2)); box-shadow: inset calc(var(--loader-size, 108px) * -.03) 0 calc(var(--loader-size, 108px) * .05) rgba(15, 23, 42, .3); animation: darma-loader-darma-b14-cocktail-shake-shake calc(var(--loader-speed, 1s) * .9) ease-in-out infinite; }
.darma-loader-darma-b14-cocktail-shake .darma-loader-darma-b14-cocktail-shake__shaker::after { content: ''; position: absolute; top: 0; left: 10%; width: 80%; height: 16%; border-radius: 4px 4px 8px 8px; background: linear-gradient(var(--accent), color-mix(in srgb, #000 28%, var(--accent))); }
.darma-loader-darma-b14-cocktail-shake .darma-loader-darma-b14-cocktail-shake__shaker span { position: absolute; width: 30%; height: 24%; border-radius: 3px; background: rgba(255, 255, 255, .68); animation: darma-loader-darma-b14-cocktail-shake-slosh calc(var(--loader-speed, 1s) * .9) ease-in-out infinite; }
.darma-loader-darma-b14-cocktail-shake .darma-loader-darma-b14-cocktail-shake__shaker span:nth-child(1) { bottom: 12%; left: 14%; }
.darma-loader-darma-b14-cocktail-shake .darma-loader-darma-b14-cocktail-shake__shaker span:nth-child(2) { bottom: 34%; left: 44%; animation-delay: calc(var(--loader-speed, 1s) * .3); }
@keyframes darma-loader-darma-b14-cocktail-shake-shake { 0%, 100% { transform: rotate(-17deg) translateY(0); } 25% { transform: rotate(15deg) translateY(-7%); } 50% { transform: rotate(-15deg) translateY(0); } 75% { transform: rotate(17deg) translateY(-7%); } }
@keyframes darma-loader-darma-b14-cocktail-shake-slosh { 0%, 100% { transform: translate(-12%, 0); } 50% { transform: translate(32%, -42%); } }

